INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38113, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "観察や実験、調査などで得られた、数値や事実の情報の集まり。", "primary_collocate": null, "pronunciation": "でーた", "ipa": "deːta", "syllable_count": 3, "sentences": [{"text": "近年、センサーやデータ解析技術を活用した「精密農業」が注目されています。", "target_word": "データ", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "データ", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "データを集める。", "target_word": "データ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "調査のデータを表にまとめました。", "target_word": "データ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "このデータは信頼できますか。", "target_word": "データ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "実験で得たデータをグラフにして発表した。", "target_word": "データ", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "データが少なすぎて、結論は出せない。", "target_word": "データ", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者は古いデータと新しいデータを比べている。", "target_word": "データ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "集めたデータによると、気温は毎年少しずつ上がっている。", "target_word": "データ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "データの正しさを確かめてから、論文を書き始める予定です。", "target_word": "データ", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "データ化", "label": "派生"}, {"form": "生データ", "label": "派生"}, {"form": "元データ", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 調査や実験で得た数値や事実の集まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 4 words above tier T1 (max 2): 日照 (Zipf 3.21), 風通し (Zipf 2.92), 変数 (Zipf 3.63), アルゴリズム (Zipf 3.83)']::text[], '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38112, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "パソコンやスマホに保存される、数字や文字、写真などの情報。", "primary_collocate": null, "pronunciation": "でーた", "ipa": "deːta", "syllable_count": 3, "sentences": [{"text": "データを保存する。", "target_word": "データ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "スマホのデータが消えてしまった。", "target_word": "データ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "このデータは容量が大きい。", "target_word": "データ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大切なデータは、必ずバックアップを取ってください。", "target_word": "データ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "写真のデータを友達に送りました。", "target_word": "データ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "データが多すぎて、アプリが重くなった。", "target_word": "データ", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "データの量が増えると、保存に時間がかかる。", "target_word": "データ", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新しい携帯に、前のデータを全部移したい。", "target_word": "データ", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "これは仕事で使うデータです。", "target_word": "データ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "データが壊れていないか確認してください。", "target_word": "データ", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 機器に保存される数字や写真などの情報", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUD