INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35079, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の子どもや若い時期など、過去の一時期を、だいたいで指す言葉。", "primary_collocate": null, "pronunciation": "ころ", "ipa": "koɾo", "syllable_count": 2, "sentences": [{"text": "それは幼い頃、何度も握りしめた懐かしい色だ。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "これは幼い頃のような単なるお絵描きではない。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "子どもの頃、よく泳いだ。", "target_word": "頃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生の頃は、毎日バスで通っていた。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若い頃の写真を見つけた。", "target_word": "頃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中学生の頃、私は大阪に住んでいた。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小さい頃の夢は、医者になることでした。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子どもの頃に戻りたいと思うことがある。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祖父は若かった頃の話をよく聞かせてくれる。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十歳の頃、初めて海を見た。", "target_word": "頃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "近頃", "label": "派生"}, {"form": "今頃", "label": "派生"}, {"form": "頃合い", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 過去の人生の時期をおおよそ指す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_ver