INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35078, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "出来事や季節に合わせて、時間のあたりをだいたいで指す言葉。", "primary_collocate": null, "pronunciation": "ころ", "ipa": "koɾo", "syllable_count": 2, "sentences": [{"text": "この頃、よく眠れない。", "target_word": "頃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毎年この頃になると、桜が咲きます。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "そろそろ家に着く頃だ。", "target_word": "頃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "その頃には、もう雨はやんでいるでしょう。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜になった頃、友達から電話が来た。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春になる頃、新しい学校が始まる。", "target_word": "頃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この頃の天気は変わりやすい。", "target_word": "頃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "みんなが集まった頃に、先生が来た。", "target_word": "頃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出発する頃には、雨が止んでいた。", "target_word": "頃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "ちょうどいい頃に、バスが来た。", "target_word": "頃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "近頃", "label": "派生"}, {"form": "今頃", "label": "派生"}, {"form": "頃合い", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 出来事や季節に合う大体の時間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid 