INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35245, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の繊維から作った、薄くて平らな素材。書いたり、印刷したり、包んだりするのに使う。", "primary_collocate": null, "pronunciation": "かみ", "ipa": "kami", "syllable_count": 2, "sentences": [{"text": "放課後の美術室で、私は白い画用紙に向き合っている。", "target_word": "紙", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "私はそのクレヨンで、紙の中央に大きな丸い太陽を描き始めた。", "target_word": "紙", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "力強く円を描くことで、言葉にできない思春期の焦燥感が、少しずつ紙の上へ溶け出していくようだった。", "target_word": "紙", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "絵師の描いた下絵を彫師が版木に彫り、摺師が紙に印刷するという複雑な工程を経ます。", "target_word": "紙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "紙に名前を書く。", "target_word": "紙", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "この紙は薄くて、とても軽い。", "target_word": "紙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "紙が足りないので、買ってきます。", "target_word": "紙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "兄は紙で小さな鳥を作ってくれた。", "target_word": "紙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "プレゼントを紙で包んで、リボンをつけた。", "target_word": "紙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古い紙は、リサイクルに出してください。", "target_word": "紙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紙袋", "label": "派生"}, {"form": "用紙", "label": "派生"}, {"form": "紙屑", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 書いたり包んだりする薄い素材", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 版木 (Zipf 2.03)']::text[], '587cc3da-cda2-4da6-b1b2-d2ff0620