INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51632, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "過ぎ去った時や場所を思い出させ、心に温かさを感じさせる様子。", "primary_collocate": null, "pronunciation": "なつかしい", "ipa": "natsɯkaʃiː", "syllable_count": 5, "sentences": [{"text": "それは幼い頃、何度も握りしめた懐かしい色だ。", "target_word": "懐かしい", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "軋む音とともに、懐かしいシナモンの匂いが記憶の奥から鮮やかに蘇り、私は思わず息を呑んだ。", "target_word": "懐かしい", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "この歌は懐かしい。", "target_word": "懐かしい", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "懐かしい町を久しぶりに歩いた。", "target_word": "懐かしい", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古いアルバムを見ると、懐かしくなる。", "target_word": "懐かしく", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母の料理の味は、いつも懐かしい。", "target_word": "懐かしい", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この駅は、昔と同じで懐かしかった。", "target_word": "懐かしかった", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "懐かしく思い出されるのは、夏の夜の花火の音だ。", "target_word": "懐かしく", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "引っ越した町に戻ると、懐かしい風景が広がっていた。", "target_word": "懐かしい", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "懐かしそうに校舎を見上げる彼の横顔が、少し寂しそうだった。", "target_word": "懐かしそうに", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "懐かしく", "label": "活用"}, {"form": "懐かしかった", "label": "活用"}, {"form": "懐かしければ", "label": "活用"}, {"form": "懐かしさ", "label": "派生"}, {"form": "懐かしむ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 昔の場所や匂いが心を温める様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 軋む (Zipf 2.32)']::text[], '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51631, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "昔のことや人を思い出して、もう一度会いたい、戻りたいと感じる様子。", "primary_collocate": null, "pronunciation": "なつかしい", "ipa": "natsɯkaʃiː", "syllable_count": 5, "sentences": [{"text": "懐かしい友達に会った。", "target_word": "懐かしい", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この写真は懐かしいですね。", "target_word": "懐かしい", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昔のおもちゃを見て、懐かしいと思った。", "target_word": "懐かしい", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "懐かしいアニメが、また始まった。", "target_word": "懐かしい", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "久しぶりに会った先生の声は、とても懐かしかった。", "target_word": "懐かしかった", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "懐かしくて、思わず笑ってしまった。", "target_word": "懐かしく", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この曲を聞くと、子どものころが懐かしくなる。", "target_word": "懐かしく", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "懐かしい人から、突然メールが届いた。", "target_word": "懐かしい", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生時代の制服を着ると、懐かしい気分になる。", "target_word": "懐かしい", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昔よく食べた駄菓子が懐かしくて、店で買ってしまった。", "target_word": "懐かしく", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "懐かしく", "label": "活用"}, {"form": "懐かしかった", "label": "活用"}, {"form": "懐かしければ", "label": "活用"}, {"form": "懐かしさ", "label": "派生"}, {"form": "懐かしむ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 昔の人や物を思い出し戻りたい感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON C