INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37309, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "夢や理想ではなく、実際に存在する状況。", "primary_collocate": null, "pronunciation": "げんじつ", "ipa": "ɡeɲdʑitsɯ", "syllable_count": 4, "sentences": [{"text": "現実の太陽は橙色だが、私が記憶の中で求める太陽は、情熱的で切ない赤色でなければならない。", "target_word": "現実", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "現実的な設計図とは異なるが、その絵には彼が求める理想の世界が詰まっている。", "target_word": "現実的な", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "夢と現実は違う。", "target_word": "現実", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "現実の世界は、思ったより厳しい。", "target_word": "現実", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼は現実から目をそらしている。", "target_word": "現実", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夢が現実になる日を待っている。", "target_word": "現実", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "現実を受け入れるのは、簡単ではありません。", "target_word": "現実", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "計画は立派だが、現実にはお金が足りない。", "target_word": "現実", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "映画を見終わって、私はゆっくり現実に戻った。", "target_word": "現実", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理想ばかり話さないで、現実を見て考えよう。", "target_word": "現実", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現実的", "label": "派生"}, {"form": "現実味", "label": "派生"}, {"form": "非現実的", "label": "派生"}, {"form": "現実化", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 理想や空想と違う実際の状況", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXC