INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37308, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本当に起きたことや、今ある出来事そのもの。", "primary_collocate": null, "pronunciation": "げんじつ", "ipa": "ɡeɲdʑitsɯ", "syllable_count": 4, "sentences": [{"text": "現実に起きたことだ。", "target_word": "現実に", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "それは現実の話ですか。", "target_word": "現実", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事故が現実に起こって、みんな驚いた。", "target_word": "現実に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "現実の出来事は、ニュースで知りました。", "target_word": "現実", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今の現実を、ありのままに話してください。", "target_word": "現実", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夢ではなく、これが現実です。", "target_word": "現実", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼の言ったことが、現実になった。", "target_word": "現実", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小説の話だと思っていたが、現実に同じ事件があった。", "target_word": "現実に", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "現実にあったことを、そのまま絵日記に書いた。", "target_word": "現実に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "現実を知ると、考え方が変わる。", "target_word": "現実", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "現実的", "label": "派生"}, {"form": "現実味", "label": "派生"}, {"form": "非現実的", "label": "派生"}, {"form": "現実化", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 本当に起きた出来事や今ある事実", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDE