INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51648, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "束縛されず、自分の考えで行動や表現ができること。", "primary_collocate": null, "pronunciation": "じゆう", "ipa": "dʑijɯː", "syllable_count": 3, "sentences": [{"text": "課題は自由な「お絵描き」だが、手には短くなった赤いクレヨンが握られている。", "target_word": "自由な", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "そこで、デザインを決める際、子供が自由に描いた絵を参考にすることにした。", "target_word": "自由に", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "自由に話していいよ。", "target_word": "自由に", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "ここでは、誰でも自由に意見を言える。", "target_word": "自由に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由を求めて、彼は旅に出た。", "target_word": "自由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "言論の自由は、民主主義の大切な土台です。", "target_word": "自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この学校は服装が自由だ。", "target_word": "自由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "規則が少ない会社では、社員は自由に働くことができる。", "target_word": "自由に", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "彼女は自由な発想で、新しい商品を考えた。", "target_word": "自由な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鳥のように自由に空を飛んでみたい。", "target_word": "自由に", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自由に", "label": "活用"}, {"form": "自由な", "label": "活用"}, {"form": "自由化", "label": "派生"}, {"form": "不自由", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 束縛されず考えや行動を選べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 絵描き (Zipf 3.6), クレヨン (Zipf 3.12), 握ら (Zipf 3.46)']::text[], '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51647, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間や物を、自分のしたいように使えること。", "primary_collocate": null, "pronunciation": "じゆう", "ipa": "dʑijɯː", "syllable_count": 3, "sentences": [{"text": "自由に使っていいよ。", "target_word": "自由に", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今日は一日、自由です。", "target_word": "自由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "午後は自由に過ごしたい。", "target_word": "自由に", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "お金を自由に使えるのは、うれしい。", "target_word": "自由に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この席は、自由に座ってください。", "target_word": "自由に", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自由な時間があれば、公園を散歩する。", "target_word": "自由な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好きなものを自由に選んでいいと言われた。", "target_word": "自由に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "週末は自由だから、一緒に映画を見よう。", "target_word": "自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由に動ける体がほしい。", "target_word": "自由に", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自由が好きな子どもは、すぐに走り出す。", "target_word": "自由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自由に", "label": "活用"}, {"form": "自由な", "label": "活用"}, {"form": "自由化", "label": "派生"}, {"form": "不自由", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 時間や物を好きに使えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587cc3da-cda2-4da6-b1b2-d2ff062025a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt