INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51778, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その日の授業が終わること。", "primary_collocate": null, "pronunciation": "ほうか", "ipa": "hoːka", "syllable_count": 3, "sentences": [{"text": "放課後の美術室で、私は白い画用紙に向き合っている。", "target_word": "放課後", "complexity_tier": "T4", "furigana": "ほうかご", "sentence_source": "mined"}, {"text": "放課後の静かな美術室で、私は窓辺の席につきクレヨンを走らせている。", "target_word": "放課後", "complexity_tier": "T5", "furigana": "ほうかご", "sentence_source": "mined"}, {"text": "放課になると、生徒たちは一斉に校庭へ走り出した。", "target_word": "放課", "complexity_tier": "T4", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課の合図を告げるチャイムが、校舎じゅうに響いた。", "target_word": "放課", "complexity_tier": "T4", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "先生は放課の前に、明日の宿題を黒板に書いた。", "target_word": "放課", "complexity_tier": "T3", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課が近づくにつれ、教室の空気がゆるんでいった。", "target_word": "放課", "complexity_tier": "T4", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課と同時に、彼女は鞄をつかんで教室を出た。", "target_word": "放課", "complexity_tier": "T3", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "この学校では、放課は午後三時半と決まっている。", "target_word": "放課", "complexity_tier": "T4", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課を待ちきれず、窓の外ばかり眺めていた。", "target_word": "放課", "complexity_tier": "T3", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課の時刻が来るまで、部活の準備には入れない。", "target_word": "放課", "complexity_tier": "T4", "furigana": "ほうか", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | その日の授業の終わり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe0b7ad-c478-4410-b461-ef7