INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51777, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "がっこうの じゅぎょうが おわる こと。", "primary_collocate": null, "pronunciation": "ほうか", "ipa": "hoːka", "syllable_count": 3, "sentences": [{"text": "放課のチャイムが鳴りました。", "target_word": "放課", "complexity_tier": "T2", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課になって、みんなが帰ります。", "target_word": "放課", "complexity_tier": "T2", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課はいつもうれしいです。", "target_word": "放課", "complexity_tier": "T2", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課まで、あと十分です。", "target_word": "放課", "complexity_tier": "T2", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "先生は放課の前に話しました。", "target_word": "放課", "complexity_tier": "T2", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課になると、校庭が静かになる。", "target_word": "放課", "complexity_tier": "T3", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "弟は放課と同時に走って帰った。", "target_word": "放課", "complexity_tier": "T3", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課を知らせる音楽が流れている。", "target_word": "放課", "complexity_tier": "T3", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課が早い日は、友だちと公園で遊ぶ。", "target_word": "放課", "complexity_tier": "T3", "furigana": "ほうか", "sentence_source": "generated"}, {"text": "放課の時間に、ろうかで友だちに会った。", "target_word": "放課", "complexity_tier": "T3", "furigana": "ほうか", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 学校の授業が終わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe0b7ad-c478-4410-b461-ef7378bc4134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUD