INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39361, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たいよう。ちきゅうに　ひかりと　ねつを　あたえる　おおきな　ほし。", "primary_collocate": null, "pronunciation": "たいよう", "ipa": "taiːjoː", "syllable_count": 4, "sentences": [{"text": "私はそのクレヨンで、紙の中央に大きな丸い太陽を描き始めた。", "target_word": "太陽", "complexity_tier": "T4", "furigana": "たいよう", "sentence_source": "mined"}, {"text": "現実の太陽は橙色だが、私が記憶の中で求める太陽は、情熱的で切ない赤色でなければならない。", "target_word": "太陽", "complexity_tier": "T6", "furigana": "たいよう", "sentence_source": "mined"}, {"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "太陽", "complexity_tier": "T5", "furigana": "たいよう", "sentence_source": "mined"}, {"text": "太陽の光が、雲の切れ間から海面に降り注いでいる。", "target_word": "太陽", "complexity_tier": "T4", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "研究者たちは、太陽の表面で起きる爆発を観測している。", "target_word": "太陽", "complexity_tier": "T4", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "地球は太陽のまわりを一年かけて回っている。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "冬の太陽は低く、部屋の奥まで光が届く。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "太陽が沈むと、街は急に冷え込んだ。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "太陽がなければ、地球上の生命は存在できない。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "山頂で見上げた太陽は、まぶしくて目を開けられなかった。", "target_word": "太陽", "complexity_tier": "T4", "furigana": "たいよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "太陽系", "label": "派生"}, {"form": "太陽光", "label": "派生"}, {"form": "太陽熱", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 地球に光と熱を与える恒星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 鶏舎 (Zipf 2.02)','sentence 3 above tier T2: contains vocabulary far above tier T2: 切れ間 (Zipf 1.88)','sentence 9 above tier T2: contains vocabulary far above tier T2: まぶしく (Zipf 2.44)']::text[], 'cbe0b7ad-c478-4410-b461-ef7378bc4134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39360, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "そらの　うえで　ひかる　まるい　もの。あつい　ひを　だして、まわりを　あかるく　する。", "primary_collocate": null, "pronunciation": "たいよう", "ipa": "taiːjoː", "syllable_count": 4, "sentences": [{"text": "太陽は空にあります。", "target_word": "太陽", "complexity_tier": "T1", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "太陽がのぼりました。", "target_word": "太陽", "complexity_tier": "T1", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "今日は太陽が出ています。", "target_word": "太陽", "complexity_tier": "T2", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "太陽はとても明るいです。", "target_word": "太陽", "complexity_tier": "T2", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "太陽の光で、体があたたかくなった。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "朝、東の空に太陽が見えた。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "あつい太陽の下で、子どもたちが遊んでいる。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "太陽を見てはいけないと、母に言われた。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "夕方になると、太陽は西にしずむ。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}, {"text": "雲がなくなって、太陽が顔を出した。", "target_word": "太陽", "complexity_tier": "T3", "furigana": "たいよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "太陽系", "label": "派生"}, {"form": "太陽光", "label": "派生"}, {"form": "太陽熱", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 空で光って暑い丸いもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: しずむ (Zipf 1.41)']::text[], 'cbe0b7ad-c478-4410-b461-ef7378bc4134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51784, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "色がついたろうでできた細い棒で、紙に絵をかく文房具。", "primary_collocate": null, "pronunciation": "くれよん", "ipa": "kɯɾejoɴ", "syllable_count": 4, "sentences": [{"text": "課題は自由な「お絵描き」だが、手には短くなった赤いクレヨンが握られている。", "target_word": "クレヨン", "complexity_tier": "T5", "furigana": "", "sentence_source": "mined"}, {"text": "私はそのクレヨンで、紙の中央に大きな丸い太陽を描き始めた。", "target_word": "クレヨン", "complexity_tier": "T4", "furigana": "", "sentence_source": "mined"}, {"text": "放課後の静かな美術室で、私は窓辺の席につきクレヨンを走らせている。", "target_word": "クレヨン", "complexity_tier": "T5", "furigana": "", "sentence_source": "mined"}, {"text": "クレヨンのざらついた質感と鮮やかな色彩が交わる瞬間、言葉にできない感情が視覚化されていく。", "target_word": "クレヨン", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "机の上には、十二色のクレヨンが並んでいる。", "target_word": "クレヨン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "彼女はクレヨンで、空を青く塗った。", "target_word": "クレヨン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "クレヨンを強く押しつけると、紙に厚い色が残る。", "target_word": "クレヨン", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "子どものころ使ったクレヨンの匂いを、今でも覚えている。", "target_word": "クレヨン", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "そのクレヨンは折れて、半分の長さになっていた。", "target_word": "クレヨン", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "クレヨンが机から転がり落ちて、床に当たった。", "target_word": "クレヨン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | ろうでできた絵をかく色棒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NUL