INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51783, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵をかくときに使う、色のついた細いぼうです。", "primary_collocate": null, "pronunciation": "くれよん", "ipa": "kɯɾejoɴ", "syllable_count": 4, "sentences": [{"text": "クレヨンで絵をかきます。", "target_word": "クレヨン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "私のクレヨンは赤です。", "target_word": "クレヨン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "クレヨンをかしてください。", "target_word": "クレヨン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "机の上にクレヨンがあります。", "target_word": "クレヨン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "弟はクレヨンで紙にいろいろな色をぬった。", "target_word": "クレヨン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "新しいクレヨンを、母が買ってくれた。", "target_word": "クレヨン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "クレヨンが短くなったので、新しいのがほしい。", "target_word": "クレヨン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "クレヨンの箱を開けると、色がきれいに並んでいた。", "target_word": "クレヨン", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "クレヨンでかいた絵を、教室にかざった。", "target_word": "クレヨン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "白いクレヨンは、白い紙の上では見えない。", "target_word": "クレヨン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 絵をかく色のついた細い棒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe0b7ad-c478-4410-b461-ef7378bc4134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET 