INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39240, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あることを、新しくやりだすこと。", "primary_collocate": null, "pronunciation": "はじめる", "ipa": "hadʑimeɾɯ", "syllable_count": 4, "sentences": [{"text": "授業を始めます。", "target_word": "始めます", "complexity_tier": "T1", "furigana": "はじめます", "sentence_source": "generated"}, {"text": "ごはんを食べ始めました。", "target_word": "始めました", "complexity_tier": "T2", "furigana": "はじめました", "sentence_source": "generated"}, {"text": "テストを始めましょう。", "target_word": "始めましょう", "complexity_tier": "T2", "furigana": "はじめましょう", "sentence_source": "generated"}, {"text": "先生が話し始めた。", "target_word": "始めた", "complexity_tier": "T1", "furigana": "はじめた", "sentence_source": "generated"}, {"text": "雨がふり始めました。", "target_word": "始めました", "complexity_tier": "T1", "furigana": "はじめました", "sentence_source": "generated"}, {"text": "私は先月、散歩を始めた。", "target_word": "始めた", "complexity_tier": "T3", "furigana": "はじめた", "sentence_source": "generated"}, {"text": "新しい日記を始めるつもりです。", "target_word": "始める", "complexity_tier": "T2", "furigana": "はじめる", "sentence_source": "generated"}, {"text": "みんなで、そうじを始めよう。", "target_word": "始めよう", "complexity_tier": "T3", "furigana": "はじめよう", "sentence_source": "generated"}, {"text": "宿題はもう始めましたか。", "target_word": "始めました", "complexity_tier": "T3", "furigana": "はじめました", "sentence_source": "generated"}, {"text": "ピアノをならい始めて、二年になる。", "target_word": "始めて", "complexity_tier": "T3", "furigana": "はじめて", "sentence_source": "generated"}], "morphological_forms": [{"form": "始めた", "label": "活用"}, {"form": "始めて", "label": "活用"}, {"form": "始めない", "label": "活用"}, {"form": "始められる", "label": "活用"}, {"form": "始め方", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 何かを新しく始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this se