INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51800, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事に対して、強い感情や熱意を持ち、夢中になること。また、その気持ち。", "primary_collocate": null, "pronunciation": "じょうねつ", "ipa": "dʑoːnetsɯ", "syllable_count": 4, "sentences": [{"text": "現実の太陽は橙色だが、私が記憶の中で求める太陽は、情熱的で切ない赤色でなければならない。", "target_word": "情熱", "complexity_tier": "T6", "furigana": "じょうねつ", "sentence_source": "mined"}, {"text": "例えば、赤は情熱や緊急を、青は信頼を連想させる。", "target_word": "情熱", "complexity_tier": "T4", "furigana": "じょうねつ", "sentence_source": "mined"}, {"text": "彼は研究に、人生をかけるほどの情熱を注いでいる。", "target_word": "情熱", "complexity_tier": "T4", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "情熱だけでは、困難な計画を成功させられない。", "target_word": "情熱", "complexity_tier": "T3", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "若い監督の作品からは、映画への情熱が伝わってくる。", "target_word": "情熱", "complexity_tier": "T4", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "年をとっても、彼女の情熱は少しも衰えなかった。", "target_word": "情熱", "complexity_tier": "T4", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "情熱を失った選手は、静かにグラウンドを去った。", "target_word": "情熱", "complexity_tier": "T4", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "教師の情熱が、生徒たちの学ぶ意欲に火をつけた。", "target_word": "情熱", "complexity_tier": "T4", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "彼は音楽に対する情熱を、決して隠そうとしない。", "target_word": "情熱", "complexity_tier": "T4", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "情熱と冷静さの両方を持つ人が、よい指導者になる。", "target_word": "情熱", "complexity_tier": "T4", "furigana": "じょうねつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "情熱的", "label": "派生"}, {"form": "情熱家", "label": "派生"}, {"form": "情熱的に", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事への強い熱意や夢中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe0b7ad-c478-4410-b461-ef7378bc4134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51799, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをとても好きで、強い気持ちがあること。", "primary_collocate": null, "pronunciation": "じょうねつ", "ipa": "dʑoːnetsɯ", "syllable_count": 4, "sentences": [{"text": "私は絵に情熱があります。", "target_word": "情熱", "complexity_tier": "T2", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "彼にはサッカーへの情熱がある。", "target_word": "情熱", "complexity_tier": "T3", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "情熱を持って、毎日練習している。", "target_word": "情熱", "complexity_tier": "T3", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "姉は料理に情熱を注いでいます。", "target_word": "情熱", "complexity_tier": "T2", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "情熱があれば、むずかしいこともできる。", "target_word": "情熱", "complexity_tier": "T3", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "先生の話から、情熱が伝わってきた。", "target_word": "情熱", "complexity_tier": "T3", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "その子の情熱は、だれにも負けない。", "target_word": "情熱", "complexity_tier": "T3", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "情熱をなくして、やめてしまう人もいる。", "target_word": "情熱", "complexity_tier": "T3", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "好きなことには、情熱が生まれるものだ。", "target_word": "情熱", "complexity_tier": "T3", "furigana": "じょうねつ", "sentence_source": "generated"}, {"text": "みんなの情熱で、大会は成功した。", "target_word": "情熱", "complexity_tier": "T3", "furigana": "じょうねつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "情熱的", "label": "派生"}, {"form": "情熱家", "label": "派生"}, {"form": "情熱的に", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | とても好きで強い気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe0b7ad-c478-4410-b461-ef7378bc4134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51802, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "力が強くて、頼りになる様子。また、意志や感情が強く感じられる様子。", "primary_collocate": null, "pronunciation": "ちからづよい", "ipa": "tɕikaɾadzɯjoi", "syllable_count": 6, "sentences": [{"text": "力強く円を描くことで、言葉にできない思春期の焦燥感が、少しずつ紙の上へ溶け出していくようだった。", "target_word": "力強く", "complexity_tier": "T6", "furigana": "ちからづよく", "sentence_source": "mined"}, {"text": "やがて成長の過程において、植物は時折厳しい気候に晒されながらも、力強く茎を伸ばしていく。", "target_word": "力強く", "complexity_tier": "T6", "furigana": "ちからづよく", "sentence_source": "mined"}, {"text": "彼は力強い声で、会場の全員に呼びかけた。", "target_word": "力強い", "complexity_tier": "T3", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "力強い筆づかいで、大きな文字が書かれていた。", "target_word": "力強い", "complexity_tier": "T3", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "選手たちは力強く地面を蹴って、前へ飛び出した。", "target_word": "力強く", "complexity_tier": "T4", "furigana": "ちからづよく", "sentence_source": "generated"}, {"text": "彼の力強い言葉が、落ち込んでいた私を励ましてくれた。", "target_word": "力強い", "complexity_tier": "T4", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "力強い握手を交わして、二人は別れた。", "target_word": "力強い", "complexity_tier": "T3", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "この橋は、力強い構造で重い車も支えている。", "target_word": "力強い", "complexity_tier": "T3", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "彼女のピアノは力強く、聴く人の胸を打った。", "target_word": "力強く", "complexity_tier": "T3", "furigana": "ちからづよく", "sentence_source": "generated"}, {"text": "若い木が力強く根を張り、風にも倒れなかった。", "target_word": "力強く", "complexity_tier": "T3", "furigana": "ちからづよく", "sentence_source": "generated"}], "morphological_forms": [{"form": "力強く", "label": "活用"}, {"form": "力強かった", "label": "活用"}, {"form": "力強くない", "label": "活用"}, {"form": "力強さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 力や意志が強く頼もしい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe0b7ad-c478-4410-b461-ef7378bc4134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51801, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "力が強くて、しっかりしている様子。", "primary_collocate": null, "pronunciation": "ちからづよい", "ipa": "tɕikaɾadzɯjoi", "syllable_count": 6, "sentences": [{"text": "この男の人は力強いです。", "target_word": "力強い", "complexity_tier": "T2", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "力強い男の人が、重い荷物を運んでくれた。", "target_word": "力強い", "complexity_tier": "T3", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "力強く、ドアを開けました。", "target_word": "力強く", "complexity_tier": "T2", "furigana": "ちからづよく", "sentence_source": "generated"}, {"text": "犬は力強く走っている。", "target_word": "力強く", "complexity_tier": "T3", "furigana": "ちからづよく", "sentence_source": "generated"}, {"text": "力強い馬が、車を引いた。", "target_word": "力強い", "complexity_tier": "T3", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "兄の腕は力強くて、たよりになる。", "target_word": "力強く", "complexity_tier": "T3", "furigana": "ちからづよく", "sentence_source": "generated"}, {"text": "力強い手で、ふたを開けてくれた。", "target_word": "力強い", "complexity_tier": "T3", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "力強く、ボールをなげた。", "target_word": "力強く", "complexity_tier": "T3", "furigana": "ちからづよく", "sentence_source": "generated"}, {"text": "力強い声で、犬がほえた。", "target_word": "力強い", "complexity_tier": "T3", "furigana": "ちからづよい", "sentence_source": "generated"}, {"text": "この犬は、力強く引っ張ります。", "target_word": "力強く", "complexity_tier": "T2", "furigana": "ちからづよく", "sentence_source": "generated"}], "morphological_forms": [{"form": "力強く", "label": "活用"}, {"form": "力強かった", "label": "活用"}, {"form": "力強くない", "label": "活用"}, {"form": "力強さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 体の力が強いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}