INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53230, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵を描くことを職業や趣味にしている人。画家。", "primary_collocate": null, "pronunciation": "えかき", "ipa": "ekaki", "syllable_count": 3, "sentences": [{"text": "課題は自由な「お絵描き」だが、手には短くなった赤いクレヨンが握られている。", "target_word": "絵描き", "complexity_tier": "T6", "furigana": "えかき", "sentence_source": "mined"}, {"text": "これは幼い頃のような単なるお絵描きではない。", "target_word": "絵描き", "complexity_tier": "T6", "furigana": "えかき", "sentence_source": "mined"}, {"text": "あの絵描きは、町の広場で絵を売っている。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "祖父は若いころ、有名な絵描きだった。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "絵描きになることが、彼の夢です。", "target_word": "絵描き", "complexity_tier": "T2", "furigana": "えかき", "sentence_source": "generated"}, {"text": "絵描きに頼んで、家族の絵を描いてもらった。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "公園で、一人の絵描きが風景を描いていた。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "この絵は、有名な絵描きの作品だ。", "target_word": "絵描き", "complexity_tier": "T2", "furigana": "えかき", "sentence_source": "generated"}, {"text": "絵描きとして生きるのは、簡単ではない。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "隣の人は、売れない絵描きだと言っていた。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}], "morphological_forms": [{"form": "絵描きさん", "label": "敬語形"}, {"form": "お絵描き", "label": "派生"}, {"form": "絵描き歌", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 絵を描くことを仕事にする人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}':