INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53229, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "絵を描くこと。子どもが好きな遊びとしての、絵を描く行為。", "primary_collocate": null, "pronunciation": "えかき", "ipa": "ekaki", "syllable_count": 3, "sentences": [{"text": "弟は絵描きが好きで、毎日クレヨンを使う。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "雨の日は、家で絵描きをして遊ぶ。", "target_word": "絵描き", "complexity_tier": "T2", "furigana": "えかき", "sentence_source": "generated"}, {"text": "子どもたちは、お絵描きに夢中になっている。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "妹と一緒に、お絵描きを楽しんだ。", "target_word": "絵描き", "complexity_tier": "T2", "furigana": "えかき", "sentence_source": "generated"}, {"text": "絵描きの時間に、先生が色を教えてくれた。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "お絵描きの道具を、かばんに入れた。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "絵描きは、子どもにとって大切な遊びだ。", "target_word": "絵描き", "complexity_tier": "T3", "furigana": "えかき", "sentence_source": "generated"}, {"text": "公園で絵描きをしてみませんか。", "target_word": "絵描き", "complexity_tier": "T2", "furigana": "えかき", "sentence_source": "generated"}, {"text": "娘は、お絵描きで赤い花を描いた。", "target_word": "絵描き", "complexity_tier": "T2", "furigana": "えかき", "sentence_source": "generated"}, {"text": "絵描きをすると、心が落ち着く。", "target_word": "絵描き", "complexity_tier": "T2", "furigana": "えかき", "sentence_source": "generated"}], "morphological_forms": [{"form": "お絵描き", "label": "派生"}, {"form": "お絵描き教室", "label": "派生"}, {"form": "絵描き歌", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 絵を描く遊びや行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-s