INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35961, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事について、自分でこうしようと選び、そう行うと定めること。", "primary_collocate": null, "pronunciation": "きめる", "ipa": "kimeɾɯ", "syllable_count": 3, "sentences": [{"text": "そこで、デザインを決める際、子供が自由に描いた絵を参考にすることにした。", "target_word": "決める", "complexity_tier": "T6", "furigana": "きめる", "sentence_source": "mined"}, {"text": "医者は体を調べて薬を決めます。", "target_word": "決めます", "complexity_tier": "T6", "furigana": "きめる", "sentence_source": "mined"}, {"text": "今日の夕飯は、私が決める。", "target_word": "決める", "complexity_tier": "T2", "furigana": "きめる", "sentence_source": "generated"}, {"text": "旅行の日にちを、みんなで決めた。", "target_word": "決めた", "complexity_tier": "T2", "furigana": "きめる", "sentence_source": "generated"}, {"text": "将来の道を決めるのは、自分自身だ。", "target_word": "決める", "complexity_tier": "T3", "furigana": "きめる", "sentence_source": "generated"}, {"text": "どの服を着るか、なかなか決められない。", "target_word": "決められない", "complexity_tier": "T3", "furigana": "きめる", "sentence_source": "generated"}, {"text": "彼は、大学に行くと決めて、勉強を始めた。", "target_word": "決めて", "complexity_tier": "T3", "furigana": "きめる", "sentence_source": "generated"}, {"text": "会議で、新しいルールを決めました。", "target_word": "決めました", "complexity_tier": "T3", "furigana": "きめる", "sentence_source": "generated"}, {"text": "決めたことは、最後までやりたい。", "target_word": "決めた", "complexity_tier": "T2", "furigana": "きめる", "sentence_source": "generated"}, {"text": "店を選ぶ前に、予算を決めておく。", "target_word": "決めて", "complexity_tier": "T2", "furigana": "きめる", "sentence_source": "generated"}], "morphological_forms": [{"form": "決めた", "label": "活用"}, {"form": "決めない", "label": "活用"}, {"form": "決められる", "label": "活用"}, {"form": "決まる", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 自分で選んで定める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e360a8-3780-4497-9898-0dec73f4ce8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41231, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "病気やけがをした人を診て、治療する仕事をしている人。", "primary_collocate": null, "pronunciation": "いしゃ", "ipa": "iɕa", "syllable_count": 2, "sentences": [{"text": "お医者さんが、病気の人の体に、他の人の体の一部を入れる医療の手順があります。", "target_word": "医者", "complexity_tier": "T6", "furigana": "いしゃ", "sentence_source": "mined"}, {"text": "医者は体を調べて薬を決めます。", "target_word": "医者", "complexity_tier": "T6", "furigana": "いしゃ", "sentence_source": "mined"}, {"text": "医者になるために、毎日勉強している。", "target_word": "医者", "complexity_tier": "T3", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "あの医者は、とても親切だと思う。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "父は、町の病院で働く医者です。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "医者に相談して、薬を変えてもらった。", "target_word": "医者", "complexity_tier": "T3", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "医者が患者の話をよく聞いてくれた。", "target_word": "医者", "complexity_tier": "T3", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "医者の説明は、わかりやすかった。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "将来は、医者として人を助けたい。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "若い医者が、けがをした人を診ている。", "target_word": "医者", "complexity_tier": "T3", "furigana": "いしゃ", "sentence_source": "generated"}], "morphological_forms": [{"form": "お医者さん", "label": "敬語形"}, {"form": "町医者", "label": "派生"}, {"form": "医者通い", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 病人を診て治療する職業の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed',