INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41230, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "病気を治す仕事をする人。具合が悪いときに行く相手。", "primary_collocate": null, "pronunciation": "いしゃ", "ipa": "iɕa", "syllable_count": 2, "sentences": [{"text": "熱があるので、医者に行った。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "医者は病気を治す仕事をしています。", "target_word": "医者", "complexity_tier": "T3", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "母は、医者を呼んでくれた。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "病気のとき、医者に診てもらうと安心だ。", "target_word": "医者", "complexity_tier": "T3", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "彼女の夢は、医者になることです。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "近所の医者は、夜も開いている。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "医者の言うとおりに、薬を飲んだ。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "医者が来るまで、静かに待っていた。", "target_word": "医者", "complexity_tier": "T3", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "おじは、医者をしている。", "target_word": "医者", "complexity_tier": "T2", "furigana": "いしゃ", "sentence_source": "generated"}, {"text": "医者を目指す学生が、勉強を続けている。", "target_word": "医者", "complexity_tier": "T3", "furigana": "いしゃ", "sentence_source": "generated"}], "morphological_forms": [{"form": "お医者さん", "label": "敬語形"}, {"form": "医者嫌い", "label": "派生"}, {"form": "町医者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 病気を治す人、通う相手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL,