INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52126, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "外から見える物事の様子や、目に見える形。", "primary_collocate": null, "pronunciation": "すがた", "ipa": "sɯɡata", "syllable_count": 3, "sentences": [{"text": "その姿を凝視する子供の瞳には、生命が持つ根源的な逞しさへの畏敬の念が宿っている。", "target_word": "姿", "complexity_tier": "T6", "furigana": "すがた", "sentence_source": "mined"}, {"text": "その姿は、まさに宇宙の摂理そのものを体現しているかのようであった。", "target_word": "姿", "complexity_tier": "T6", "furigana": "すがた", "sentence_source": "mined"}, {"text": "山の上から、町の姿がよく見える。", "target_word": "姿", "complexity_tier": "T2", "furigana": "すがた", "sentence_source": "generated"}, {"text": "雨があがって、美しい森の姿が現れた。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "これが、この島の本当の姿だ。", "target_word": "姿", "complexity_tier": "T2", "furigana": "すがた", "sentence_source": "generated"}, {"text": "古い写真に、昔の駅の姿が残っている。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "朝日に照らされた湖の姿は、静かだった。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "工事が終わって、新しい橋の姿が見えてきた。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "この絵は、冬の山の姿を描いている。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "遠くに、小さな船の姿が見えた。", "target_word": "姿", "complexity_tier": "T2", "furigana": "すがた", "sentence_source": "generated"}], "morphological_forms": [{"form": "後ろ姿", "label": "派生"}, {"form": "姿形", "label": "派生"}, {"form": "姿見", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 外から見える物の様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 逞し (Zipf 2.19)']::text[], 'e1e360a8-3780-4497-9898-0dec73f4ce8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52125, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人の見た目や形。人がそこにいて目に見える様子。", "primary_collocate": null, "pronunciation": "すがた", "ipa": "sɯɡata", "syllable_count": 3, "sentences": [{"text": "窓の外に、母の姿が見えた。", "target_word": "姿", "complexity_tier": "T2", "furigana": "すがた", "sentence_source": "generated"}, {"text": "彼は、りっぱな姿で式に出た。", "target_word": "姿", "complexity_tier": "T2", "furigana": "すがた", "sentence_source": "generated"}, {"text": "ステージで歌う姉の姿は、輝いていた。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "友だちの姿が見えなくなるまで、手をふった。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "走る選手の姿を、カメラで写した。", "target_word": "姿", "complexity_tier": "T2", "furigana": "すがた", "sentence_source": "generated"}, {"text": "暗い道で、人の姿を見てほっとした。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "先生の姿を見ると、みんな席についた。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "着物を着た姿が、とてもきれいだ。", "target_word": "姿", "complexity_tier": "T2", "furigana": "すがた", "sentence_source": "generated"}, {"text": "子どもの寝ている姿を見ると、うれしくなる。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}, {"text": "彼女は、あっという間に姿を消した。", "target_word": "姿", "complexity_tier": "T3", "furigana": "すがた", "sentence_source": "generated"}], "morphological_forms": [{"form": "後ろ姿", "label": "派生"}, {"form": "姿形", "label": "派生"}, {"form": "花嫁姿", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人の見た目や体の形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e