INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52002, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が始まる最初の段階。まだ小さいが、これから大きく成長する可能性があるもの。", "primary_collocate": null, "pronunciation": "ほうが", "ipa": "hoːɡa", "syllable_count": 3, "sentences": [{"text": "彼は泥にまみれながら、日々屋外にて植物の萌芽を見守る。", "target_word": "萌芽", "complexity_tier": "T6", "furigana": "ほうが", "sentence_source": "mined"}, {"text": "不確実性の高い技術的課題に挑む起業家に対し、リスクマネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "萌芽", "complexity_tier": "T6", "furigana": "ほうが", "sentence_source": "mined"}, {"text": "春になり、町に新しい商売の萌芽が見られた。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "小さな萌芽を、大切に育てたい。", "target_word": "萌芽", "complexity_tier": "T2", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "新しい技術の萌芽が、この町で生まれた。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "それは、大きな変化の萌芽かもしれない。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "小さな失敗の中にも、成功の萌芽がある。", "target_word": "萌芽", "complexity_tier": "T2", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "子の才能の萌芽を、先生は見つけた。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "研究に、新しい考えの萌芽が見えてきた。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "才能の萌芽を守るために、親は子を見守っている。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}], "morphological_forms": [{"form": "萌芽期", "label": "派生"}, {"form": "萌芽的", "label": "派生"}, {"form": "萌芽する", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | これから育つ小さな始まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e360a8-3780-4497-9898-0dec73f4ce8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52001, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが始まる最初の小さなもの。", "primary_collocate": null, "pronunciation": "ほうが", "ipa": "hoːɡa", "syllable_count": 3, "sentences": [{"text": "平和への萌芽が、少しずつ現れている。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "彼の言葉に、変化の萌芽を感じた。", "target_word": "萌芽", "complexity_tier": "T2", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "この小説には、後の名作の萌芽がある。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "新しい文化の萌芽は、小さな町から始まった。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "萌芽のうちに、問題を見つけることが大切だ。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "小さな萌芽でも、育てれば大きくなる。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "そのアイデアは、まだ萌芽にすぎない。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "若い画家の絵に、才能の萌芽が見える。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "社会が変わる萌芽を、みんなで探している。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}, {"text": "これは、新しい産業の萌芽と言える。", "target_word": "萌芽", "complexity_tier": "T3", "furigana": "ほうが", "sentence_source": "generated"}], "morphological_forms": [{"form": "萌芽期", "label": "派生"}, {"form": "萌芽的", "label": "派生"}, {"form": "萌芽する", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 何かが始まる最初の兆し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e360a8-3780-4497-9898-0dec73f4ce8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52400, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "眼球の中央にある、光を取り入れる黒い部分。", "primary_collocate": null, "pronunciation": "ひとみ", "ipa": "çitomi", "syllable_count": 3, "sentences": [{"text": "その姿を凝視する子供の瞳には、生命が持つ根源的な逞しさへの畏敬の念が宿っている。", "target_word": "瞳", "complexity_tier": "T6", "furigana": "ひとみ", "sentence_source": "mined"}, {"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "瞳", "complexity_tier": "T6", "furigana": "ひとみ", "sentence_source": "mined"}, {"text": "暗い部屋では、瞳が大きくなる。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "猫の瞳は、夜になると丸くなる。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "光が強いと、瞳は小さくなります。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "医者が、患者の瞳にライトを当てた。", "target_word": "瞳", "complexity_tier": "T3", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "彼女の瞳は、深い茶色をしている。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "瞳に光が入ると、まぶしく感じる。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "子どもは、大きな瞳で空を見上げた。", "target_word": "瞳", "complexity_tier": "T3", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "瞳の色は、人によってちがう。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 目の中央の光を通す部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 凝視 (Zipf 3.17), 逞し (Zipf 2.19), 畏敬 (Zipf 2.76), 宿っ (Zipf 3.16)','sentence 1 above tier T3: 5 words above tier T3 (max 3): 窓辺 (Zipf 2.97), 佇む (Zipf 2.76), 幼き (Zipf 2.71), 白銀 (Zipf 3.03), 庭先 (Zipf 2.68)']::text[], 'e1e360a8-3780-4497-9898-0dec73f4ce8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52399, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "目のこと。感情や気持ちが表れる目。", "primary_collocate": null, "pronunciation": "ひとみ", "ipa": "çitomi", "syllable_count": 3, "sentences": [{"text": "彼女の瞳は、星のように輝いていた。", "target_word": "瞳", "complexity_tier": "T3", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "その瞳に見つめられて、言葉が出なかった。", "target_word": "瞳", "complexity_tier": "T3", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "母は、やさしい瞳で私を見た。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "少女の瞳から、涙がこぼれた。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "澄んだ瞳の赤ちゃんが、笑っている。", "target_word": "瞳", "complexity_tier": "T3", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "彼は、まっすぐな瞳で夢を話した。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "瞳を閉じると、昔の景色が見える。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "愛する人の瞳を、いつまでも忘れない。", "target_word": "瞳", "complexity_tier": "T3", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "犬は、悲しそうな瞳でこちらを見ていた。", "target_word": "瞳", "complexity_tier": "T3", "furigana": "ひとみ", "sentence_source": "generated"}, {"text": "瞳が合って、二人は笑った。", "target_word": "瞳", "complexity_tier": "T2", "furigana": "ひとみ", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 感情が表れる目のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e360a8-3780-4497-9898-0dec73f4ce8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
