INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52404, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間の子供。特に親から見た自分の子供。", "primary_collocate": null, "pronunciation": "こ", "ipa": "ko", "syllable_count": 1, "sentences": [{"text": "裏庭の片隅に設えられた僅かな土塊、すなわち小さな花壇は、幼き子にとって広大な宇宙の縮図であった。", "target_word": "子", "complexity_tier": "T6", "furigana": "こ", "sentence_source": "mined"}, {"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "子", "complexity_tier": "T6", "furigana": "こ", "sentence_source": "mined"}, {"text": "母は子を朝早く起こした。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "私の子は今年六歳になる。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "親は子の将来を心配している。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "彼は子に絵本を読んでやった。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "うちの子が熱を出して休んでいる。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "父親は一人の子を連れて公園へ行った。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "子のために毎朝お弁当を作っている。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "母として、子の笑顔を見るのが一番うれしい。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}], "morphological_forms": [{"form": "子供", "label": "派生"}, {"form": "子ども", "label": "派生"}, {"form": "親子", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 親から見た自分の子供", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 設え (Zipf 2.0), 土塊 (Zipf 1.72)','sentence 1 above tier T1: 8 words above tier T1 (max 2): 窓辺 (Zipf 2.97), 佇む (Zipf 2.76), 幼き (Zipf 2.71), 白銀 (Zipf 3.03), 覆わ (Zipf 3.84), 庭先 (Zipf 2.68)']::text[], '286390ce-0447-431c-b554-5d3f880b0ae5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52403, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "子どものこと。赤ちゃんや小さい人。", "primary_collocate": null, "pronunciation": "こ", "ipa": "ko", "syllable_count": 1, "sentences": [{"text": "あの子は三歳ぐらいだと思う。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "小さな子が道でころんで泣いている。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "公園で知らない子と遊んだ。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "赤ちゃんが生まれて、かわいい子だと言われた。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "隣の席の子は、とても元気だ。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "迷子の子を交番まで連れて行った。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "その子にはまだ字が読めない。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "眠っている子を起こさないでください。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "近所の子と一緒に帰った。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}, {"text": "大きな声で泣く子がいて、先生が来た。", "target_word": "子", "complexity_tier": "T3", "furigana": "こ", "sentence_source": "generated"}], "morphological_forms": [{"form": "子供", "label": "派生"}, {"form": "子ども", "label": "派生"}, {"form": "子たち", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 赤ちゃんや小さな子ども", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c-b554-5d3f880b0ae5') ON CO