INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51512, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "面積が非常に大きいさま。", "primary_collocate": null, "pronunciation": "こうだい", "ipa": "koːdai", "syllable_count": 4, "sentences": [{"text": "裏庭の片隅に設えられた僅かな土塊、すなわち小さな花壇は、幼き子にとって広大な宇宙の縮図であった。", "target_word": "広大", "complexity_tier": "T6", "furigana": "こうだい", "sentence_source": "mined"}, {"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "広大", "complexity_tier": "T6", "furigana": "こうだい", "sentence_source": "mined"}, {"text": "広大な草原が地平線まで続いている。", "target_word": "広大", "complexity_tier": "T3", "furigana": "こうだい", "sentence_source": "generated"}, {"text": "この大学は広大な敷地を持っている。", "target_word": "広大", "complexity_tier": "T3", "furigana": "こうだい", "sentence_source": "generated"}, {"text": "北海道には広大な牧場が多い。", "target_word": "広大", "complexity_tier": "T3", "furigana": "こうだい", "sentence_source": "generated"}, {"text": "飛行機から広大な砂漠が見えた。", "target_word": "広大", "complexity_tier": "T3", "furigana": "こうだい", "sentence_source": "generated"}, {"text": "森は広大で、一日では歩けない。", "target_word": "広大", "complexity_tier": "T3", "furigana": "こうだい", "sentence_source": "generated"}, {"text": "広大な海を前に、船は小さく見えた。", "target_word": "広大", "complexity_tier": "T3", "furigana": "こうだい", "sentence_source": "generated"}, {"text": "彼らは広大な土地を買って家を建てた。", "target_word": "広大", "complexity_tier": "T3", "furigana": "こうだい", "sentence_source": "generated"}, {"text": "この国の国土は広大だ。", "target_word": "広大", "complexity_tier": "T3", "furigana": "こうだい", "sentence_source": "generated"}], "morphological_forms": [{"form": "広大な", "label": "活用"}, {"form": "広大に", "label": "活用"}, {"form": "広大さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 面積が非常に大きいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-co