INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51640, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物事の端の方、または場所の隅の部分。", "primary_collocate": null, "pronunciation": "かたすみ", "ipa": "katasumi", "syllable_count": 4, "sentences": [{"text": "裏庭の片隅に設えられた僅かな土塊、すなわち小さな花壇は、幼き子にとって広大な宇宙の縮図であった。", "target_word": "片隅", "complexity_tier": "T6", "furigana": "かたすみ", "sentence_source": "mined"}, {"text": "庭の片隅に、子供のための遊び小屋を建てる計画が持ち上がった。", "target_word": "片隅", "complexity_tier": "T6", "furigana": "かたすみ", "sentence_source": "mined"}, {"text": "彼は町の片隅で小さな店を開いている。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "心の片隅に、不安が残っていた。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "世界の片隅で、誰かが静かに祈っている。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "紙の片隅に、小さな絵がかいてあった。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "机の片隅に、古い写真が置いてある。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "彼女は頭の片隅でその約束を覚えていた。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "駅の片隅に、小さな花が咲いている。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "ニュースの片隅に、その事故が載っていた。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 場所や物事の端の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contain