INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51639, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "へやのすみっこのこと。", "primary_collocate": null, "pronunciation": "かたすみ", "ipa": "katasumi", "syllable_count": 4, "sentences": [{"text": "部屋の片隅に、小さな本棚がある。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "猫は部屋の片隅で丸くなっている。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "教室の片隅に、ほうきが立ててあった。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "私は片隅の席に座って、本を読んだ。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "弟は片隅で一人で遊んでいた。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "台所の片隅に、箱が置いてある。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "片隅にほこりがたまっていた。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "彼は片隅に荷物を置いて、休んだ。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "広間の片隅には、古いピアノがある。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}, {"text": "押し入れの片隅から、昔のおもちゃが出てきた。", "target_word": "片隅", "complexity_tier": "T3", "furigana": "かたすみ", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | へやのすみっこ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c-b554-5d3f880b0ae5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET con