INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37945, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が生まれる、いちばんもととなる部分や力。", "primary_collocate": null, "pronunciation": "こんげん", "ipa": "koŋɡeɴ", "syllable_count": 4, "sentences": [{"text": "その姿を凝視する子供の瞳には、生命が持つ根源的な逞しさへの畏敬の念が宿っている。", "target_word": "根源", "complexity_tier": "T6", "furigana": "こんげん", "sentence_source": "mined"}, {"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "根源", "complexity_tier": "T6", "furigana": "こんげん", "sentence_source": "mined"}, {"text": "戦争の根源には、貧しさがあると言われる。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "この問題の根源を、みんなで考えてみよう。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "生命の根源は、水にあると考えられている。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "悲しみの根源を知れば、心が軽くなる。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "彼は争いの根源を取り除こうと努力した。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "力の根源は、毎日の小さな努力だ。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "すべての悪の根源は欲だという人もいる。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "原因を探ると、根源は意外に単純だった。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}], "morphological_forms": [{"form": "根源的", "label": "派生"}, {"form": "根源的な", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事を生む一番のもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c-b554-5d3f880b0ae5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37944, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "すべてのものの、いちばんもとになるものです。", "primary_collocate": null, "pronunciation": "こんげん", "ipa": "koŋɡeɴ", "syllable_count": 4, "sentences": [{"text": "神は万物の根源だと、昔の人は信じた。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "古代の哲学者は、世界の根源を問い続けた。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "水が万物の根源だと言った人がいた。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "宇宙の根源は、まだ誰にも分からない。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "根源にあるものは、とても単純だそうだ。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "学者は物質の根源を調べている。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "自然は、すべての命の根源である。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "彼は根源から考え直そうとした。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "光の根源は太陽だ。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "根源を問う心が、学問を生んだ。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}], "morphological_forms": [{"form": "根源的", "label": "派生"}, {"form": "根源的な", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | すべての物の一番のもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c