INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52474, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "心身が強く、困難に負けないさま。", "primary_collocate": null, "pronunciation": "たくましい", "ipa": "takɯmaɕiː", "syllable_count": 5, "sentences": [{"text": "その姿を凝視する子供の瞳には、生命が持つ根源的な逞しさへの畏敬の念が宿っている。", "target_word": "逞しさ", "complexity_tier": "T6", "furigana": "たくましい", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "逞しさ", "complexity_tier": "T6", "furigana": "たくましい", "sentence_source": "mined"}, {"text": "彼女は逞しい心で、苦しい日々を乗り越えた。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しく生きる彼の姿に、勇気をもらった。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "失敗しても立ち上がる逞しい人だ。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "困難に負けない逞しさを身につけたい。", "target_word": "逞しさ", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "母は逞しく、一人で三人の子を育てた。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい精神が、チームを救った。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "彼は逞しくて、何があっても笑っている。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい若者たちが、町を元気にしている。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}], "morphological_forms": [{"form": "逞しく", "label": "活用"}, {"form": "逞しかった", "label": "活用"}, {"form": "逞しくない", "label": "活用"}, {"form": "逞しさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 心