INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52473, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "体が丈夫で元気な様子。", "primary_collocate": null, "pronunciation": "たくましい", "ipa": "takɯmaɕiː", "syllable_count": 5, "sentences": [{"text": "彼は腕の逞しい漁師だ。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい体の男が、重い荷物を運んだ。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "毎日泳いで、体が逞しくなった。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい馬が、丘を走っていく。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "父は肩が広くて、逞しい人だ。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい腕で、彼は子どもを持ち上げた。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "弟は野菜をたくさん食べて、逞しく育った。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい体つきの選手が入場した。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "筋肉のついた逞しい胸を、彼は張った。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "病気が治って、彼はまた逞しくなった。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}], "morphological_forms": [{"form": "逞しく", "label": "活用"}, {"form": "逞しかった", "label": "活用"}, {"form": "逞しくない", "label": "活用"}, {"form": "逞しさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 体が丈夫で元気なさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"