INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52566, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の本質的な部分を小さくまとめて示したもの。または、全体を縮めて表した図や模型。", "primary_collocate": null, "pronunciation": "しゅくず", "ipa": "ɕɯkɯzɯ", "syllable_count": 3, "sentences": [{"text": "裏庭の片隅に設えられた僅かな土塊、すなわち小さな花壇は、幼き子にとって広大な宇宙の縮図であった。", "target_word": "縮図", "complexity_tier": "T6", "furigana": "しゅくず", "sentence_source": "mined"}, {"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "縮図", "complexity_tier": "T6", "furigana": "しゅくず", "sentence_source": "mined"}, {"text": "この町は日本の社会の縮図だ。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "学校はいわば小さな社会の縮図である。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "満員電車は現代生活の縮図だと思う。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "この小説は、時代の縮図を描いている。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "市場には人間社会の縮図がある。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "家族は社会の縮図だと言われる。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "その村は、国全体の縮図のようだった。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "クラスの様子は、世の中の縮図に見える。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 全体の本質を小さく示したもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c-b554-5d3f880b0ae5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52565, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小さい（ちいさい）絵（え）のように、大きなものごとの大切（たいせつ）なところだけをうつし出（だ）したもの。", "primary_collocate": null, "pronunciation": "しゅくず", "ipa": "ɕɯkɯzɯ", "syllable_count": 3, "sentences": [{"text": "地図は、広い土地の縮図である。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "先生は黒板に学校の縮図をかいた。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "町の縮図を見て、道を確かめた。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "この模型は、城の縮図としてよくできている。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "縮図を広げて、旅行の計画を立てた。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "一万分の一の縮図で、町の形を示した。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "子どもたちは、教室の縮図を紙に作った。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "縮図を見ると、全体の形がよく分かる。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "縮図と実物をくらべて、違いを探した。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "机の上に、島の縮図が広げてあった。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 全体を縮めて表した図や模型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c-b554-5d3f880b0ae5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
