INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36113, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "言葉や絵、音楽などで表したり伝えたりする、心の気持ち。", "primary_collocate": null, "pronunciation": "かんじょう", "ipa": "kaɲdʑoː", "syllable_count": 4, "sentences": [{"text": "クレヨンのざらついた質感と鮮やかな色彩が交わる瞬間、言葉にできない感情が視覚化されていく。", "target_word": "感情", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "この憧れの感情は、やがてグローバルな大衆向けブランドによって巧妙に咀嚼され、誰もが手が届く価格帯へと昇華されるのだ。", "target_word": "感情", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "歌に感情を込める。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "絵で感情を伝えます。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "感情のこもった歌に拍手が起きた。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "言葉にできない感情は、音楽が語ってくれる。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情が声に乗ると、せりふは生きた言葉になる。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "感情を込めて読めば、聞き手にも気持ちが伝わる。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "手紙には、言葉にならなかった感情が丁寧に書かれていた。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "作家は登場人物の感情を細かく描くことで、読者の心を強く動かした。", "target_word": "感情", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "感情的", "label": "派生"}, {"form": "感情表現", "label": "派生"}, {"form": "感情移入", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 表現して伝える心の気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: ざらつい (Zipf 1.67)']: