INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36112, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "うれしい、悲しい、怒りなど、心の中に自然にわいてくる気持ちそのもの。", "primary_collocate": null, "pronunciation": "かんじょう", "ipa": "kaɲdʑoː", "syllable_count": 4, "sentences": [{"text": "感情が顔に出る。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "強い感情がわいた。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "悲しい感情をおさえました。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "感情は人によって違います。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "うれしい感情が心にあふれてきた。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "怒りの感情を、ぐっとこらえている。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情をことばにするのは難しいです。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情を抑えられなくなって、思わず泣いてしまった。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "驚きや喜びといった感情は、誰にでも自然に起こるものだ。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "試合に負けた悔しい感情がなかなか消えず、その夜はほとんど眠れなかった。", "target_word": "感情", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "感情的", "label": "派生"}, {"form": "感情表現", "label": "派生"}, {"form": "感情移入", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 心の中にわく喜怒哀楽の気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51630, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "色や形、記憶や技などが、はっきりと目立って見事な様子。また、記憶などがありありと思い出される様子。", "primary_collocate": null, "pronunciation": "あざやか", "ipa": "azaɟaka", "syllable_count": 4, "sentences": [{"text": "クレヨンのざらついた質感と鮮やかな色彩が交わる瞬間、言葉にできない感情が視覚化されていく。", "target_word": "鮮やかな", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "軋む音とともに、懐かしいシナモンの匂いが記憶の奥から鮮やかに蘇り、私は思わず息を呑んだ。", "target_word": "鮮やかに", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "記憶が鮮やかだ。", "target_word": "鮮やかだ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昔の夢を鮮やかに覚えています。", "target_word": "鮮やかに", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼の演技は鮮やかでした。", "target_word": "鮮やかで", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鮮やかな手さばきで魚をさばいていた。", "target_word": "鮮やかな", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "その日の光景が鮮やかによみがえった。", "target_word": "鮮やかに", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鮮やかに決まった逆転ゴールに、観客は総立ちになった。", "target_word": "鮮やかに", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "子どものころの旅の記憶は、今でも鮮やかだ。", "target_word": "鮮やかだ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "彼女は難しい問題を鮮やかな解き方で片づけ、教室中を驚かせた。", "target_word": "鮮やかな", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "鮮やかな", "label": "活用"}, {"form": "鮮やかに", "label": "活用"}, {"form": "鮮やかだ", "label": "活用"}, {"form": "鮮やかさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 色や記憶や技が際立って見事な様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: ざらつい (Zipf 1.67)']::text[], 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51629, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "色がとても濃くはっきりしていて、きれいな様子。", "primary_collocate": null, "pronunciation": "あざやか", "ipa": "azaɟaka", "syllable_count": 4, "sentences": [{"text": "鮮やかな赤だ。", "target_word": "鮮やかな", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "この花は鮮やかだ。", "target_word": "鮮やかだ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "空の青が鮮やかでした。", "target_word": "鮮やかで", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "このシャツの色は鮮やかです。", "target_word": "鮮やかで", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鮮やかに咲いた花を写真にとった。", "target_word": "鮮やかに", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鮮やかな緑の葉が雨にぬれている。", "target_word": "鮮やかな", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋になると、山は鮮やかに色づいて美しくなる。", "target_word": "鮮やかに", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "この絵は色がとても鮮やかで、見ているだけで元気が出る。", "target_word": "鮮やかで", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "オレンジの鮮やかさに目を引かれた。", "target_word": "鮮やかさ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "夕日に照らされた海は、燃えるような鮮やかな赤に染まっていた。", "target_word": "鮮やかな", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "鮮やかな", "label": "活用"}, {"form": "鮮やかに", "label": "活用"}, {"form": "鮮やかだ", "label": "活用"}, {"form": "鮮やかさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 色がはっきりして美しい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, mo