INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53334, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "職業や地位、役職などを得て、その立場で働き始める。", "primary_collocate": null, "pronunciation": "つく", "ipa": "tsɯkɯ", "syllable_count": 2, "sentences": [{"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "就く", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "彼は教師の職に就く。", "target_word": "就く", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "兄は医者の仕事に就きました。", "target_word": "就きました", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "まだ仕事に就いていません。", "target_word": "就いて", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父は長年、大切な役職に就いている。", "target_word": "就いて", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新しい部長の座に就いた人を紹介する。", "target_word": "就いた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学を出たら、人を助ける仕事に就きたいと考えている。", "target_word": "就きたい", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "彼は議長の任に就いて、会議を進めることになった。", "target_word": "就いて", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "経験を積んだ人ほど、責任の重い地位に就く。", "target_word": "就く", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "彼女は若くして国の重要な役職に就き、多くの人々の期待を背負うことになった。", "target_word": "就き", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "就いた", "label": "活用"}, {"form": "就いて", "label": "活用"}, {"form": "就かない", "label": "活用"}, {"form": "就きます", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 職業や地位を得てその立場に入る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id,