INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53333, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "学校を出た人などが、初めて仕事を得て働き始める。", "primary_collocate": null, "pronunciation": "つく", "ipa": "tsɯkɯ", "syllable_count": 2, "sentences": [{"text": "春から仕事に就く。", "target_word": "就く", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "姉は店の仕事に就いた。", "target_word": "就いた", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "四月に、初めての仕事に就きます。", "target_word": "就きます", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟はやっと仕事に就きました。", "target_word": "就きました", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学を出て、会社の仕事に就いた。", "target_word": "就いた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卒業してすぐ、新しい仕事に就いている。", "target_word": "就いて", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仕事に就く前に、働くルールをしっかり覚えておきたい。", "target_word": "就く", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "初めて仕事に就いたとき、毎日が新しいことばかりだった。", "target_word": "就いた", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "仕事に就けば、自分でお金をかせげる。", "target_word": "就けば", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "学校を卒業した若者たちは、それぞれ希望する仕事に就き、新しい生活を始めた。", "target_word": "就き", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "就いた", "label": "活用"}, {"form": "就いて", "label": "活用"}, {"form": "就かない", "label": "活用"}, {"form": "就きます", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 初めての仕事を得て働き始める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.conte