INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51812, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がそばに立ったり座ったりして過ごす、窓のすぐそばの場所。", "primary_collocate": null, "pronunciation": "まどべ", "ipa": "madobe", "syllable_count": 3, "sentences": [{"text": "放課後の静かな美術室で、私は窓辺の席につきクレヨンを走らせている。", "target_word": "窓辺", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "窓辺", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "彼は窓辺に立つ。", "target_word": "窓辺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窓辺は明るい。", "target_word": "窓辺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "私は窓辺で本を読みます。", "target_word": "窓辺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "母は窓辺の席に座りました。", "target_word": "窓辺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窓辺で外を見ている少女がいた。", "target_word": "窓辺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窓辺に立つと、冷たい風を感じた。", "target_word": "窓辺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨の日は、窓辺でお茶を飲みながら音楽を聞く。", "target_word": "窓辺", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "彼は窓辺に寄りかかって、遠くの山をぼんやり眺めていた。", "target_word": "窓辺", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 人が過ごす窓のそばの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors