INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51811, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "花や鉢、小さな物を置いて飾る、窓のすぐそばの場所。", "primary_collocate": null, "pronunciation": "まどべ", "ipa": "madobe", "syllable_count": 3, "sentences": [{"text": "窓辺に花がある。", "target_word": "窓辺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窓辺の鉢は小さい。", "target_word": "窓辺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窓辺に鉢を置きました。", "target_word": "窓辺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窓辺には日がよく当たります。", "target_word": "窓辺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窓辺は日当たりがよい。", "target_word": "窓辺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窓辺にかざった花が咲いた。", "target_word": "窓辺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窓辺に置いた植物に水をやる。", "target_word": "窓辺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窓辺に並べた小さな人形が、朝の光に照らされていた。", "target_word": "窓辺", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "窓辺にサボテンを置いておけば、手間をかけずに育てられる。", "target_word": "窓辺", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "母が窓辺に飾ったガラスのびんは、夕方になると赤く光って見えた。", "target_word": "窓辺", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 物を置いて飾る窓のそばの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, vali