INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52444, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "厳粛", "is_correct": true, "explanation": "正解。「げんしゅく」と読む。"}, {"text": "原則", "is_correct": false, "explanation": "「げんそく」。音が一つだけ違う別の語。"}, {"text": "減収", "is_correct": false, "explanation": "「げんしゅう」。音が一つだけ違う別の語。"}, {"text": "原色", "is_correct": false, "explanation": "「げんしょく」。音が一つだけ違う別の語。"}], "explanations": {"厳粛": "正解。「げんしゅく」と読む。", "原則": "「げんそく」。音が一つだけ違う別の語。", "減収": "「げんしゅう」。音が一つだけ違う別の語。", "原色": "「げんしょく」。音が一つだけ違う別の語。"}, "sentence_index": null, "correct_answer": "厳粛"}, "level_3": {"options": [{"text": "乱暴に", "is_correct": false, "explanation": "「乱暴に」では文の意味が通らない。"}, {"text": "厳粛に", "is_correct": true, "explanation": "正解。この文脈に合う。"}, {"text": "派手に", "is_correct": false, "explanation": "「派手に」では文の意味が通らない。"}, {"text": "退屈に", "is_correct": false, "explanation": "「退屈に」では文の意味が通らない。"}], "explanations": {"乱暴に": "「乱暴に」では文の意味が通らない。", "厳粛に": "正解。この文脈に合う。", "派手に": "「派手に」では文の意味が通らない。", "退屈に": "「退屈に」では文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "厳粛に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厳粛なケーキを食べました。", "explanation": "ケーキのような食べ物に「厳粛な」は使えない。"}, {"text": "今日の天気は厳粛でした。", "explanation": "天気を「厳粛」とは言わない。"}, {"text": "厳粛な冗談を言ってみんなで笑った。", "explanation": "「厳粛」と冗談で笑う場面は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea692bf-fe53-44c2-8f3e-caec1a8b843a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
