INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36689, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の心の働きや、心の持ち方。考え方や気持ちの動き、意志などを含む、心の全体を表す言葉。", "primary_collocate": null, "pronunciation": "せいしん", "ipa": "seːɕiɴ", "syllable_count": 4, "sentences": [{"text": "ロボット工学の深淵を志す者がまず体現すべきは、DIYの精神に根ざした泥臭い試行錯誤のプロセスに他ならない。", "target_word": "精神", "complexity_tier": "T6", "furigana": "せいしん", "sentence_source": "mined"}, {"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "精神的", "complexity_tier": "T6", "furigana": "せいしんてき", "sentence_source": "mined"}, {"text": "彼の精神は、チームの誰よりも強い。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "挑戦する精神を忘れてはいけません。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "この学校の教育は、自主性を重んじる精神に基づいている。", "target_word": "精神", "complexity_tier": "T4", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "失敗しても、その精神は変わらなかった。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "法律の精神を理解することが大切だ。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "彼らの精神は代々受け継がれてきた。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "彼女は不屈の精神で最後まで走り抜いた。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "開拓者の精神に学びたい。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}], "morphological_forms": [{"form": "精神的", "label": "派生"}, {"form": "精神力", "label": "派生"}, {"form": "精神論", "label": "派生"}, {"form": "精神性", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 心の持ち方・基本姿勢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 7 words above tier T1 (max 2): 深淵 (Zipf 3.16), 志す (Zipf 3.1), 体現 (Zipf 3.4), diy (Zipf 3.44), 根ざし (Zipf 2.82), 泥臭い (Zipf 2.6)','sentence 1 above tier T1: 5 words above tier T1 (max 2): 多忙 (Zipf 3.57), 就く (Zipf 3.43), 書斎 (Zipf 3.25), 昼食 (Zipf 3.9), 充足 (Zipf 3.05)','sentence 8 above tier T1: contains vocabulary far above tier T1: 走り抜い (Zipf 1.23)']::text[], 'f4a32954-d7c9-438d-a77f-6039c0b280e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36688, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心で考える力や感じる心のこと。頭だけでなく、気持ちもふくめて、人の心の中にあるもの。", "primary_collocate": null, "pronunciation": "せいしん", "ipa": "seːɕiɴ", "syllable_count": 4, "sentences": [{"text": "精神と体は、つながっています。", "target_word": "精神", "complexity_tier": "T2", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "運動すると、精神が落ち着く。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "彼は精神を集中して試験に臨んだ。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "毎日の仕事で、精神がつかれました。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "精神の健康は体の健康と同じくらい大切です。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "精神を休ませるために、散歩に出かけた。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "その事件は、彼女の精神に大きな傷を残した。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "精神が不安定なときは、無理をしないほうがいい。", "target_word": "精神", "complexity_tier": "T4", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "精神を鍛えるには、時間がかかる。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}, {"text": "好きな音楽を聞くと、精神が安定する。", "target_word": "精神", "complexity_tier": "T3", "furigana": "せいしん", "sentence_source": "generated"}], "morphological_forms": [{"form": "精神的", "label": "派生"}, {"form": "精神力", "label": "派生"}, {"form": "精神面", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 体と対になる心の働き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a32954-d7c9-438d-a77f-6039c0b280e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35669, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある動作や出来事が終わった後の時間や位置を表す。", "primary_collocate": null, "pronunciation": "あと", "ipa": "ato", "syllable_count": 2, "sentences": [{"text": "しかる後に、プログラミングという「神経系」を構築し、抽象的論理と物理的挙動を厳密に同期させるのだ。", "target_word": "後", "complexity_tier": "T6", "furigana": "あと", "sentence_source": "mined"}, {"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "後", "complexity_tier": "T6", "furigana": "あと", "sentence_source": "mined"}, {"text": "会議の後で、結果を報告します。", "target_word": "後", "complexity_tier": "T2", "furigana": "あと", "sentence_source": "generated"}, {"text": "雨が止んだ後、空に虹が出た。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "手術を終えた後に、患者は静かに眠った。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "その後の経過は良好です。", "target_word": "後", "complexity_tier": "T2", "furigana": "あと", "sentence_source": "generated"}, {"text": "問題が解決した後も、調査は続けられた。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "契約を結んだ後で、変更は認められない。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "試合の後には、必ず全員で反省会を開く。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "事故の後、彼の生活は一変した。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}], "morphological_forms": [{"form": "後で", "label": "派生"}, {"form": "後ほど", "label": "派生"}, {"form": "その後", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 出来事の終了より後の時点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'cla