INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35668, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが終わったあと。", "primary_collocate": null, "pronunciation": "あと", "ipa": "ato", "syllable_count": 2, "sentences": [{"text": "食事の後に、歯をみがきます。", "target_word": "後", "complexity_tier": "T2", "furigana": "あと", "sentence_source": "generated"}, {"text": "宿題は後でやります。", "target_word": "後", "complexity_tier": "T2", "furigana": "あと", "sentence_source": "generated"}, {"text": "後から友だちが来るよ。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "お風呂の後は、すぐに寝る。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "授業が終わった後、図書館へ行った。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "雨の後の道はぬれている。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "旅行の後、写真を整理した。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "帰った後で、電話がありました。", "target_word": "後", "complexity_tier": "T2", "furigana": "あと", "sentence_source": "generated"}, {"text": "寝る前でなく、起きた後に勉強する。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "ケーキを食べた後、お茶を飲んだ。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}], "morphological_forms": [{"form": "後で", "label": "派生"}, {"form": "後から", "label": "派生"}, {"form": "後ほど", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 何かが終わった時点より後", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a32954-d7c9-438d-a77f-6039c0b280e5') ON CONFLICT (sense_