INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37595, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自然の現象や物体の動きの法則を研究する学問分野。", "primary_collocate": null, "pronunciation": "ぶつり", "ipa": "bɯtsɯɾi", "syllable_count": 3, "sentences": [{"text": "電子工作により、センサーやアクチュエータといった「感覚器官」と「筋肉」を物理的に実装する。", "target_word": "物理的", "complexity_tier": "T6", "furigana": "ぶつりてき", "sentence_source": "mined"}, {"text": "しかる後に、プログラミングという「神経系」を構築し、抽象的論理と物理的挙動を厳密に同期させるのだ。", "target_word": "物理的", "complexity_tier": "T6", "furigana": "ぶつりてき", "sentence_source": "mined"}, {"text": "彼女の人生におけるこの学校の初日は、単なる物理的な場所の移動を意味するものではない。", "target_word": "物理的", "complexity_tier": "T6", "furigana": "ぶつりてき", "sentence_source": "mined"}, {"text": "彼は大学院で物理を研究している。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の法則は、宇宙のどこでも変わらない。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "量子の世界を扱う物理は、直感に反することが多い。", "target_word": "物理", "complexity_tier": "T4", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の発展が、現代の技術を支えてきた。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "彼女は物理で博士号を取得した。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の知識がなければ、この実験は理解できない。", "target_word": "物理", "complexity_tier": "T4", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "アインシュタインは物理に革命をもたらした。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理学", "label": "派生"}, {"form": "物理的", "label": "派生"}, {"form": "物理学者", "label": "派生"}, {"form": "物理法則", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 自然法則を研究する学問", "colloc