INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37594, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物の動きや力について考える学問のことです。", "primary_collocate": null, "pronunciation": "ぶつり", "ipa": "bɯtsɯɾi", "syllable_count": 3, "sentences": [{"text": "物理は、むずかしいです。", "target_word": "物理", "complexity_tier": "T2", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "私は物理が好きです。", "target_word": "物理", "complexity_tier": "T2", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "明日、物理のテストがあります。", "target_word": "物理", "complexity_tier": "T2", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理を勉強すると、ボールの動きが分かる。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "兄は高校で物理を教えている。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の宿題が多くて、困っている。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の先生は、実験をよく見せてくれる。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "力と運動を学ぶ物理は、身近な学問だ。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理が苦手なので、友達に教えてもらった。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "来年は物理と化学を選ぶつもりだ。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理学", "label": "派生"}, {"form": "物理的", "label": "派生"}, {"form": "物理室", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 力と運動を学ぶ学校の教科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 