INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36463, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事に触れて生じる、心や体の反応や気持ち。五感（視覚・聴覚・嗅覚・味覚・触覚）や、時間・空間などの抽象的なものに対する感じ方も含む。", "primary_collocate": null, "pronunciation": "かんかく", "ipa": "kaɴkaku", "syllable_count": 4, "sentences": [{"text": "電子工作により、センサーやアクチュエータといった「感覚器官」と「筋肉」を物理的に実装する。", "target_word": "感覚", "complexity_tier": "T6", "furigana": "かんかく", "sentence_source": "mined"}, {"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "感覚的", "complexity_tier": "T6", "furigana": "かんかくてき", "sentence_source": "mined"}, {"text": "長く歩くと、足の感覚がなくなってきた。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "彼には時間の感覚が全くない。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "新しい靴の感覚にようやく慣れてきた。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "彼女は色に対する感覚が優れている。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "久しぶりに泳ぐと、昔の感覚を取り戻せた。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "この薬を飲むと、指先がしびれる感覚がある。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "空間の感覚をつかむには、実際に歩いて確かめるのがよい。", "target_word": "感覚", "complexity_tier": "T4", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "彼の感覚は、周りの人とは少しずれている。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}], "morphological_forms": [{"form": "感覚的", "label": "派生"}, {"form": "感覚器官", "label": "派生"}, {"form": "感覚器", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 五感や物事への感じ方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アクチュエータ (Zipf 2.3)','sentence 1 above tier T2: contains vocabulary far above tier T2: アペラシオン (Zipf 1.01)']::text[], 'f4a32954-d7c9-438d-a77f-6039c0b280e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36462, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを感じる力のこと。例えば、暑いと感じたり、悲しいと感じたりするときの気持ち。", "primary_collocate": null, "pronunciation": "かんかく", "ipa": "kaɴkaku", "syllable_count": 4, "sentences": [{"text": "暑いという感覚は、人によってちがう。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "悲しい感覚が、胸に広がった。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "赤ちゃんは、生まれてすぐに感覚が働く。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "目をとじると、音の感覚がはっきりする。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "ふしぎな感覚がして、後ろをふり向いた。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "この感覚を言葉にするのは、むずかしい。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "うれしい感覚が、いつまでも消えなかった。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "病気で、味の感覚がなくなってしまった。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "初めて空を飛ぶ感覚は、忘れられない。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}, {"text": "感覚が鋭い人は、小さな音にも気づく。", "target_word": "感覚", "complexity_tier": "T3", "furigana": "かんかく", "sentence_source": "generated"}], "morphological_forms": [{"form": "感覚的", "label": "派生"}, {"form": "感覚器官", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 暑さや悲しさを感じる気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', '