INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53404, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飲料などを飲むための、ガラス製の容器。", "primary_collocate": null, "pronunciation": "ぐらす", "ipa": "ɡɯɾasɯ", "syllable_count": 3, "sentences": [{"text": "熟練したソムリエは、グラス内で展開される鉱物的な輪郭や土壌由来の複雑な香気構造を解読し、視覚や嗅覚を超えた土地的コンテキストを味覚的に再構成する。", "target_word": "グラス", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "ソムリエは、グラスを回して香りを確かめた。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "脚の長いグラスにワインを注ぐ。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "乾杯の前に、グラスをそっと合わせた。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "薄いグラスは、洗うときに割れやすい。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "食器棚には、ワイン用のグラスが六つ並んでいる。", "target_word": "グラス", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "彼はグラスを傾けて、色の深みを眺めた。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "グラスの縁に口をつけ、ゆっくり味わった。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "この店では、料理に合わせてグラスを替えてくれる。", "target_word": "グラス", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "グラスが空になると、店員がすぐに注ぎに来た。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "個", "label": "助数詞"}, {"form": "ワイングラス", "label": "派生"}, {"form": "ショットグラス", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | ワインなどを注ぐ脚付きの器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted f