INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53403, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "グラスは飲み物を入れるガラスのコップです。", "primary_collocate": null, "pronunciation": "ぐらす", "ipa": "ɡɯɾasɯ", "syllable_count": 3, "sentences": [{"text": "グラスに水を入れます。", "target_word": "グラス", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "グラスが一つ割れた。", "target_word": "グラス", "complexity_tier": "T1", "furigana": "", "sentence_source": "generated"}, {"text": "冷たいお茶をグラスにそそいだ。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "テーブルにグラスを二つ置いてください。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "このグラスは、電子レンジに使えない。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "妹はグラスで牛乳を飲んでいる。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "氷の入ったグラスから、水滴が落ちた。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "グラスを洗ってから、棚にもどした。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "コップよりグラスのほうが、飲み物がおいしく見える。", "target_word": "グラス", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "手がすべって、グラスを落としてしまった。", "target_word": "グラス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "個", "label": "助数詞"}, {"form": "ワイングラス", "label": "派生"}, {"form": "ビールグラス", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 飲み物を入れるガラスのコップ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a32