INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52000, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "経験や学習によって得られた知識や見識。", "primary_collocate": null, "pronunciation": "ちけん", "ipa": "tɕikeɴ", "syllable_count": 3, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "知見", "complexity_tier": "T6", "furigana": "ちけん", "sentence_source": "mined"}, {"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "知見", "complexity_tier": "T6", "furigana": "ちけん", "sentence_source": "mined"}, {"text": "専門家の知見を参考に、計画を見直した。", "target_word": "知見", "complexity_tier": "T3", "furigana": "ちけん", "sentence_source": "generated"}, {"text": "長年の研究から、多くの知見が得られた。", "target_word": "知見", "complexity_tier": "T3", "furigana": "ちけん", "sentence_source": "generated"}, {"text": "新しい知見を共有するため、報告会が開かれる。", "target_word": "知見", "complexity_tier": "T3", "furigana": "ちけん", "sentence_source": "generated"}, {"text": "彼女は医療に関する深い知見を持っている。", "target_word": "知見", "complexity_tier": "T3", "furigana": "ちけん", "sentence_source": "generated"}, {"text": "この調査は、今後の対策に役立つ知見をもたらした。", "target_word": "知見", "complexity_tier": "T4", "furigana": "ちけん", "sentence_source": "generated"}, {"text": "現場で得た知見を、論文にまとめた。", "target_word": "知見", "complexity_tier": "T3", "furigana": "ちけん", "sentence_source": "generated"}, {"text": "若手にも知見を伝える機会が必要だ。", "target_word": "知見", "complexity_tier": "T3", "furigana": "ちけん", "sentence_source": "generated"}, {"text": "過去の失敗から学んだ知見は、何よりも貴重だ。", "target_word": "知見", "complexity_tier": "T3", "furigana": "ちけん", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 経験や研究で得た見識", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: アペラシオン (Zipf 1.01)']::text[], 'f4a32954-d7c9-438d-a77f-6039c0b280e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
